urlset:
{%- for p in config.extra.static_pages %}

  {{ config.base_url }}{{ p.path }}
  {{ p.lastmod }}

{%- endfor %}
{%- set blog = get_section(path="blog/_index.md") %}

  {{ blog.permalink | safe }}
  {% set newest = blog.pages | first %}{{ newest.date | date(format="%Y-%m-%d") }}

{%- for page in blog.pages %}

  {{ (config.base_url ~ page.path) | trim_end(pat="/") }}
  {% if page.updated %}{{ page.updated }}{% else %}{{ page.date | date(format="%Y-%m-%d") }}{% endif %}

{%- endfor %}
